      reply: () => {
        attempts += 1;
        return attempts === 1 ? json({ beats: [beat({ entryRanges: [{ sessionId: 's1', from: 0, to: 99 }] })] }) : json({ beats: [beat()] });
      },
    });
    const ingest: Stage<IngestArtifact> = { name: 'ingest', maxAttempts: 1, run: async () => ({ artifact: twoSessions() }) };
